import re,os
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
def parse(key):
    m=re.search(re.escape(key)+r' \((\d+)x(\d+)\):\n',t)
    h,w=int(m[1]),int(m[2])
    return [list(map(int,r.split())) for r in t[m.end():].split('\n')[:h]]
I1=parse('Demo pair 1 input'); O1=parse('Demo pair 1 output')
I2=parse('Demo pair 2 input'); O2=parse('Demo pair 2 output')

def comps(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx] and (ny,nx) not in seen:
                                seen.add((ny,nx)); st.append((ny,nx))
                out.append(cells)
    return out

def sil(cells):
    ys=[y for y,x in cells]; xs=[x for y,x in cells]
    y0,x0=min(ys),min(xs); h=max(ys)-y0+1; w=max(xs)-x0+1
    return [[1 if (y0+r,x0+c) in set(cells) else 0 for c in range(w)] for r in range(h)]

